warp:
vec3 mus;
vec2 rs, uv1, uv6, uv7, uv8;
float dx,dy;
shader_body
{
vec2 _uv = uv;

_uv = uv_orig;
uv1 = (_uv-.5) * aspect.xy;

//BACKGROUND
float z = 16.0*length(uv1)+time;
vec2 uvn = vec2(normalize(uv1));
rs = clamp(tan(z)*uvn,-5.0,5.0)/2.0;

//CRYSTAL
float mult = q31;
uv7 = sin(uv1*mult);
uv8 = uv7;
float dist = length(uv8);
dist *= (abs(uv1.x) + abs(uv1.y))+ q32;

float ang2 = atan (uv8.y,uv8.x);
ang2 =  .1*floor (16.0* ang2);
vec2 dir = .5*uv8+vec2 (cos(ang2), sin(ang2));


z = (1.0-cos(8.0*dist));
z = clamp(z, 0.0, 1.0);

//ADD
float mask = float(z >= .5); //momentan beliebig
rs = q28*rs + (1.0-q28)*rs.yx;
_uv += (1.0-mask)*.03*(rs.yx) + .5*mask*z*normalize(dir);

//ZENTRALSTRAHL
uv6 = (mat2(_qb) * uv1);
mus = vec3(abs(0.01/(sqrt(uv6.x)+.001))*(rad+.2));

//DOTS
vec2 uv2 = .7*uv1+.3*sin(uv1*16.0+4.0*vec2 (q5,q6));
uv2 *= .2;
vec3 dots = vec3(q26*clamp(.001/(length(uv2)), 0.0, 1.0));
vec3 blur = ((texture(sampler_blur1, fract(_uv)).xyz * scale1) + bias1);
vec3 crisp= texture(sampler_main, _uv).xyz;
vec3 diff = (crisp) - .5*blur;
vec3 ret1 = crisp + mus + dots;

vec3 mod = texture (sampler_noise_lq,.5*_uv+time*.01).xyz-.2;
mod = 1.0 - mod*diff;

ret = (1.0-mask)*ret1*mod + mask*ret1*mod;
ret = ret *.98- .03;




}

comp:
vec3 ret1, neu, crisp, blur;
vec2 uv2, uv3;

shader_body
{
float ang2, c, s;
uv -= 0.5;
uv *= aspect.xy;    

vec2 tmp = vec2(uv);
float dist = 1.0;
float inten = 1.0;
float mask = 0.0;
ret1 = vec3(0.0);
float anz = 3.0;
float n = 0.0;
float t_rel = q29;
while (n <= anz) {
    ang2 = 6.28*n/anz+q30;
    c = cos(ang2);
    s = sin(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;
    uv2*= aspect.yx;

    dist = 1.0-fract(n/anz+t_rel); //evtl sqrt !

    inten =  4.0*dist*(1.0-dist*dist);
    uv3 = 3.0*uv2*dist + 0.5+.0*vec2(q5,q6);
    crisp = texture(sampler_main, uv3).xyz;
    blur = ((texture(sampler_blur1, fract(uv3)).xyz * scale1) + bias1) * vec3 (.8,.9,1.0);
    ret1 = max(ret1,(crisp+blur)*inten);
n++;
}


vec3 ret1 = ret1 ;
//ret1 = texture(sampler_main, .5+uv_orig*aspect.yx*1.2).xyz;


ret = ret1;

}
